def transform(grid):
    """Restore cells obscured by color 3 using 180-degree rotational symmetry."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    unresolved = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 3:
                rr, cc = h - 1 - r, w - 1 - c
                if grid[rr][cc] != 3:
                    out[r][c] = grid[rr][cc]
                else:
                    unresolved.append((r, c))

    # If a covered cell and its rotational counterpart are both hidden, use
    # the surrounding unhidden cells (as in the repeated interior pattern).
    for r, c in unresolved:
        neighbors = []
        for rr, cc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
            if 0 <= rr < h and 0 <= cc < w and grid[rr][cc] != 3:
                neighbors.append(grid[rr][cc])
        if neighbors:
            counts = Counter(neighbors)
            out[r][c] = min(counts, key=lambda value: (-counts[value], neighbors.index(value)))
        else:
            visible = [grid[rr][cc] for rr in range(h) for cc in range(w) if grid[rr][cc] != 3]
            counts = Counter(visible)
            out[r][c] = counts.most_common(1)[0][0]

    return out


